initJs:
function(container, apiUrl, tables) {
  let currentPredictions = [];
  let chartType = 'line';

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの再描画
  function renderPredictions(predictions) {
    const tbody = container.querySelector('#prediction-table-body');
    tbody.innerHTML = predictions.map(p => `
      <tr data-id="${p.予測結果ID}">
        <td>${p.商品コード || '-'}</td>
        <td>${p.商品名 || '-'}</td>
        <td>${p.予測対象日 ? new Date(p.予測対象日).toLocaleDateString() : '-'}</td>
        <td>${p.予測数量 || 0}</td>
        <td>${p.予測精度 || 0}%</td>
        <td>${p.推奨発注数量 || 0}</td>
        <td>${p.実績数量 || '-'}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 0.8rem; 
                       background: ${p.予測ステータス === '完了' ? '#28a745' : p.予測ステータス === 'エラー' ? '#dc3545' : '#ffc107'}; 
                       color: white;">
            ${p.予測ステータス || '未実行'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${p.予測結果ID}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawPredictionChart(predictions) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!predictions || predictions.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('予測データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの準備
    const sortedData = predictions.sort((a, b) => new Date(a.予測対象日) - new Date(b.予測対象日));
    const maxValue = Math.max(...sortedData.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データポイントの描画
    if (chartType === 'line') {
      // 予測値の線
      ctx.strokeStyle = '#007bff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      sortedData.forEach((d, i) => {
        const x = padding + (i / (sortedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((d.予測数量 || 0) / maxValue) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 実績値の線
      ctx.strokeStyle = '#28a745';
      ctx.lineWidth = 2;
      ctx.beginPath();
      sortedData.forEach((d, i) => {
        if (d.実績数量) {
          const x = padding + (i / (sortedData.length - 1)) * chartWidth;
          const y = canvas.height - padding - (d.実績数量 / maxValue) * chartHeight;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    } else {
      // 棒グラフ
      const barWidth = chartWidth / sortedData.length * 0.8;
      sortedData.forEach((d, i) => {
        const x = padding + (i / sortedData.length) * chartWidth;

        // 予測値
        ctx.fillStyle = '#007bff';
        const predHeight = ((d.予測数量 || 0) / maxValue) * chartHeight;
        ctx.fillRect(x, canvas.height - padding - predHeight, barWidth / 2, predHeight);

        // 実績値
        if (d.実績数量) {
          ctx.fillStyle = '#28a745';
          const actualHeight = (d.実績数量 / maxValue) * chartHeight;
          ctx.fillRect(x + barWidth / 2, canvas.height - padding - actualHeight, barWidth / 2, actualHeight);
        }
      });
    }

    // 凡例
    ctx.fillStyle = '#007bff';
    ctx.fillRect(canvas.width - 150, 20, 15, 15);
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', canvas.width - 130, 32);

    ctx.fillStyle = '#28a745';
    ctx.fillRect(canvas.width - 150, 40, 15, 15);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', canvas.width - 130, 52);
  }

  // 比較チャート描画
  function drawComparisonChart(predictions) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!predictions || predictions.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('比較データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 実績データがある予測のみ
    const comparisonData = predictions.filter(p => p.実績数量);

    if (comparisonData.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('実績データがまだありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 散布図として描画
    const maxValue = Math.max(...comparisonData.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));

    comparisonData.forEach(d => {
      const x = padding + ((d.予測数量 || 0) / maxValue) * chartWidth;
      const y = canvas.height - padding - ((d.実績数量 || 0) / maxValue) * chartHeight;

      ctx.fillStyle = '#007bff';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });

    // 理想線（y=x）
    ctx.strokeStyle = '#dc3545';
    ctx.lineWidth = 1;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, padding);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const models = container.querySelectorAll('input[name="prediction-model"]:checked');

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!startDate || !endDate) {
      showError('予測期間を設定してください');
      return false;
    }
    if (new Date(startDate) >= new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }
    if (new Date(startDate) < new Date()) {
      showError('開始日は現在日以降の日付を設定してください');
      return false;
    }
    if (models.length === 0) {
      showError('予測モデルを選択してください');
      return false;
    }

    return true;
  }

  // AI予測実行
  async function executePrediction() {
    if (!validateForm()) return;

    const loadingDiv = container.querySelector('#prediction-loading');
    const resultsDiv = container.querySelector('#prediction-results');

    loadingDiv.classList.remove('hidden');
    resultsDiv.classList.add('hidden');

    try {
      // 模擬的な予測処理（実際のAI処理の代替）
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 模擬予測結果の生成
      const storeId = container.querySelector('#store-select').value;
      const category = container.querySelector('#category-select').value;
      const startDate = new Date(container.querySelector('#start-date').value);
      const endDate = new Date(container.querySelector('#end-date').value);

      const mockPredictions = [];
      const currentDate = new Date(startDate);
      let productIndex = 1;

      while (currentDate <= endDate) {
        const prediction = {
          予測結果ID: `pred-${Date.now()}-${productIndex}`,
          店舗ID: storeId,
          商品ID: `product-${productIndex}`,
          商品コード: `P${String(productIndex).padStart(4, '0')}`,
          商品名: `${category}商品${productIndex}`,
          予測対象日: new Date(currentDate).toISOString(),
          予測数量: Math.floor(Math.random() * 100) + 20,
          予測精度: Math.floor(Math.random() * 20) + 80,
          推奨発注数量: Math.floor(Math.random() * 120) + 30,
          実績数量: Math.random() > 0.7 ? Math.floor(Math.random() * 100) + 15 : null,
          予測ステータス: '完了',
          予測モデルバージョン: 'v2.1.0'
        };
        mockPredictions.push(prediction);

        currentDate.setDate(currentDate.getDate() + 1);
        if (productIndex < 5) productIndex++;
        else productIndex = 1;
      }

      currentPredictions = mockPredictions;

      // 予測結果の保存
      for (const prediction of mockPredictions) {
        await window.aivicApi.save(6, prediction); // 需要予測結果テーブル
      }

      // 結果表示
      renderPredictions(currentPredictions);
      drawPredictionChart(currentPredictions);
      drawComparisonChart(currentPredictions);

      // 精度指標の更新
      const avgAccuracy = currentPredictions.reduce((sum, p) => sum + (p.予測精度 || 0), 0) / currentPredictions.length;
      container.querySelector('#accuracy-rate').textContent = `${avgAccuracy.toFixed(1)}%`;
      container.querySelector('#confidence-interval').textContent = '95%';
      container.querySelector('#model-version').textContent = 'v2.1.0';

      // 影響要因分析の更新
      container.querySelector('#seasonal-impact').textContent = '中程度 (15%)';
      container.querySelector('#weather-impact').textContent = '高 (25%)';
      container.querySelector('#event-impact').textContent = '低 (5%)';

      // 外部要因情報の更新
      container.querySelector('#weather-info').textContent = '晴れ時々曇り、気温22-28℃';
      container.querySelector('#event-info').textContent = '地域祭り (影響度: 中)';

      loadingDiv.classList.add('hidden');
      resultsDiv.classList.remove('hidden');

    } catch (error) {
      loadingDiv.classList.add('hidden');
      showError('予測処理中にエラーが発生しました: ' + error.message);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentPredictions.length === 0) {
      showError('エクスポートする予測データがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '予測精度', '推奨発注数量', '実績数量', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentPredictions.map(p => [
        p.商品コード || '',
        p.商品名 || '',
        p.予測対象日 ? new Date(p.予測対象日).toLocaleDateString() : '',
        p.予測数量 || 0,
        (p.予測精度 || 0) + '%',
        p.推奨発注数量 || 0,
        p.実績数量 || '',
        p.予測ステータス || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // イベントリスナー
  container.querySelector('#btn-predict').addEventListener('click', executePrediction);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelectorAll('input[name="prediction-model"]').forEach(cb => cb.checked = false);
    container.querySelector('#prediction-results').classList.add('hidden');
    currentPredictions = [];
  });

  container.querySelector('#btn-chart-line').addEventListener('click', () => {
    chartType = 'line';
    drawPredictionChart(currentPredictions);
  });

  container.querySelector('#btn-chart-bar').addEventListener('click', () => {
    chartType = 'bar';
    drawPredictionChart(currentPredictions);
  });

  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  container.querySelector('#product-search').addEventListener('input', (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = currentPredictions.filter(p => 
      (p.商品名 || '').toLowerCase().includes(keyword) ||
      (p.商品コード || '').toLowerCase().includes(keyword)
    );
    renderPredictions(filtered);
  });

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const predictionId = detailBtn.dataset.id;
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面
    }
  });
}
